-- a8a97cbc | ما حق الوالدين في الأسرة؟
UPDATE qa_questions SET
  answer = 'حقُّ الوالدين قرنه اللهُ بحقِّه هو: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا﴾ [الإسراء: ٢٣]، قال ابن كثير: «ولهذا قرن بعبادته بر الوالدين» (ج٥/ص٦٤). وهو أمرٌ بالإحسان لا مجرَّدُ كفٍّ عن الأذى، وحدودُه في الآية نفسِها: تركُ أدنى القول السيئ — قال ابن كثير: «حتى ولا التأفيف الذي هو أدنى مراتب القول السيئ» — وتركُ الفعل القبيح، والقولُ الكريم، وخفضُ جناح الذل من الرحمة، والدعاءُ لهما: ﴿وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا﴾ [الإسراء: ٢٤]. ويبقى برُّهما بعد موتهما في أربع خصالٍ نصَّ عليها حديثُ أبي أسيدٍ الساعديّ: «الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما، وإكرام صديقهما» (تفسير ابن كثير، ج٥/ص٦٦).',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): الإسراء ٢٣-٢٤؛ تفسير القرآن العظيم لابن كثير (ت السلامة): ج٥/ص٦٤ وج٥/ص٦٦ (تفسير سورة الإسراء) | الكلمات المفتاحية: أسرة، والدين، بر',
  evidence = 'الآيتان بتمامهما: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوٓا۟ إِلَّآ إِيَّاهُ وَبِٱلْوَٰلِدَيْنِ إِحْسَٰنًا ۚ إِمَّا يَبْلُغَنَّ عِندَكَ ٱلْكِبَرَ أَحَدُهُمَآ أَوْ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفٍّۢ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًۭا كَرِيمًۭا﴾ ﴿وَٱخْفِضْ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحْمَةِ وَقُل رَّبِّ ٱرْحَمْهُمَا كَمَا رَبَّيَانِى صَغِيرًۭا﴾ [الإسراء: ٢٣-٢٤]. وقال ابن كثير عندها: «ولهذا قرن بعبادته بر الوالدين فقال: (وَبِالْوَالِدَيْنِ إِحْسَانًا) أي: وأمر بالوالدين إحسانًا»، ثم فسّر النهيَ: «(فَلا تَقُلْ لَهُمَا أُفٍّ) أي: لا تسمعهما قولا سيئًا، حتى ولا التأفيف الذي هو أدنى مراتب القول السيئ (وَلا تَنْهَرْهُمَا) أي: ولا يصدر منك إليهما فعل قبيح» (ج٥/ص٦٤). وساق في الموضع نفسِه حديثَ أبي أسيدٍ الساعديّ في برِّهما بعد موتهما: «نعم، خصال أربع: الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما، وإكرام صديقهما، وصلة الرحم التي لا رحم لك إلا من قبلهما» رواه أحمد وأبو داود وابن ماجه (ج٥/ص٦٦).',
  verification_status = 'verified'
WHERE id = 'a8a97cbc-5771-49bc-8be7-cf1f84fd4670'
  AND reference = 'القرآن الكريم؛ تفسير ابن كثير | الكلمات المفتاحية: أسرة، والدين، بر'
  AND evidence = 'قال تعالى: ﴿وَبِالْوَالِدَيْنِ إِحْسَانًا﴾ [الإسراء: 23].'
  AND answer = 'بر الوالدين واجب عظيم ومن أعظم القربات بعد حق الله.';

-- a81f7eca | ما معنى الاستطاعة في الحج؟
UPDATE qa_questions SET
  answer = 'الاستطاعةُ المشروطةُ في ﴿مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًۭا﴾ [آل عمران: ٩٧] فسَّرها المرفوعُ الذي ساقه ابن كثير عند الآية بـ«الزَّادُ والرَّاحِلَة» (ج٢/ص٨٢)، أي: ما يبلِّغه إلى البيت ويردُّه من نفقةٍ ومركب. ثم هي عنده قسمان: «تارة يكون الشخص مستطيعا بنفسه، وتارة بغيره» — فدخلت القدرةُ البدنيّةُ بنفسه، والنيابةُ عمّن عجز عنها. وما وراء ذلك من تفصيل الشروط أحاله ابن كثير نفسُه إلى كتب الأحكام: «كما هو مقرر في كتب الأحكام»، فلا يُحمَّل الموضعُ ما ليس فيه.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): آل عمران ٩٧؛ تفسير القرآن العظيم لابن كثير (ت السلامة): ج٢/ص٨٢-٨٣ (تفسير سورة آل عمران) | الكلمات المفتاحية: حج، استطاعة، نسك',
  evidence = '﴿وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلْبَيْتِ مَنِ ٱسْتَطَاعَ إِلَيْهِ سَبِيلًۭا﴾ [آل عمران: ٩٧]. وقد فسَّر «السبيل» المرفوعُ الذي ساقه ابن كثير عند الآية: «فقام آخر فقال: ما السبيل يا رسول الله ؟ قال: "الزَّادُ والرَّاحِلَة"» رواه الترمذيّ وابن ماجه (ج٢/ص٨٢)، وله شواهد في الموضع نفسِه، منها ما رواه الحاكم عن أنس: «سئل عن قول الله: (مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلا) فقيل ما السبيل ؟ قال: "الزَّاد والرَّاحِلَة"» ثم قال: «صحيح على شرط مسلم، ولم يخرجاه» (ج٢/ص٨٣). وقسمةُ الاستطاعة منصوصةٌ عند ابن كثير: «وأما الاستطاعة فأقسام: تارة يكون الشخص مستطيعا بنفسه، وتارة بغيره، كما هو مقرر في كتب الأحكام» (ج٢/ص٨٢).',
  verification_status = 'verified'
WHERE id = 'a81f7eca-c7f3-487d-ad60-1a22c236aedf'
  AND reference = 'القرآن الكريم؛ تفسير ابن كثير | الكلمات المفتاحية: حج، استطاعة، نسك'
  AND evidence = 'قال تعالى: ﴿وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا﴾ [آل عمران: 97].'
  AND answer = 'الاستطاعة تشمل القدرة البدنية والمالية وأمن الطريق ونحو ذلك مما يتمكن به المسلم من أداء النسك.';

-- a2384a73 | ما معنى توحيد العبادة؟
UPDATE qa_questions SET
  answer = 'توحيدُ العبادة: إفرادُ الله بالقصد في كلِّ عبادة، لا في أنواعٍ معدودةٍ منها؛ قال السعدي عند ﴿وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ﴾ [البينة: ٥]: «قاصدين بجميع عباداتهم الظاهرة والباطنة وجه الله، وطلب الزلفى لديه»، وفسّر ﴿حُنَفَآءَ﴾ بـ«معرضين [مائلين] عن سائر الأديان المخالفة لدين التوحيد» (ص٩٣١). ويجمع ذلك قولُه: ﴿قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ﴾ [الأنعام: ١٦٢]. وخُصَّت الصلاةُ والزكاةُ بالذكر في آية البيّنة «لفضلهما وشرفهما، وكونهما العبادتين اللتين من قام بهما قام بجميع شرائع الدين»؛ وهذا التوحيدُ والإخلاصُ هو «دِينُ الْقَيِّمَةِ أي: الدين المستقيم».',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): البينة ٥، والأنعام ١٦٢؛ تيسير الكريم الرحمن للسعدي (ت اللويحق): ص٩٣١ (تفسير سورة البينة) | الكلمات المفتاحية: التوحيد، العبادة، الإخلاص',
  evidence = '﴿وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ﴾ [البينة: ٥]. قال السعدي في تفسيرها: «فما أمروا في سائر الشرائع إلا أن يعبدوا {اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ} أي: قاصدين بجميع عباداتهم الظاهرة والباطنة وجه الله، وطلب الزلفى لديه، {حُنَفَاءَ} أي: معرضين [مائلين] عن سائر الأديان المخالفة لدين التوحيد»، ثم قال: «وخص الصلاة والزكاة [بالذكر] مع أنهما داخلان في قوله {لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ} لفضلهما وشرفهما، وكونهما العبادتين اللتين من قام بهما قام بجميع شرائع الدين»، وقال: «{وَذَلِكَ} أي التوحيد والإخلاص في الدين، هو {دِينُ الْقَيِّمَةِ} أي: الدين المستقيم» (ص٩٣١). وجِماعُ ذلك في قوله: ﴿قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ﴾ [الأنعام: ١٦٢].',
  verification_status = 'verified'
WHERE id = 'a2384a73-aafe-4085-8bbd-fd6fe9192d14'
  AND reference = 'القرآن الكريم؛ تفسير السعدي | الكلمات المفتاحية: التوحيد، العبادة، الإخلاص'
  AND evidence = 'قال تعالى: ﴿وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ﴾ [البينة: 5].'
  AND answer = 'إفراد الله تعالى بجميع أنواع العبادة كالدعاء والصلاة والذبح والنذر، فلا يصرف منها شيء لغير الله.';

-- df203e32 | ما مقصود النكاح في الشريعة؟
UPDATE qa_questions SET
  answer = 'مقاصدُ النكاح المنصوصةُ في الآية ثلاثة: السكنُ ﴿لِّتَسْكُنُوٓا۟ إِلَيْهَا﴾، والمودّةُ والرحمةُ ﴿وَجَعَلَ بَيْنَكُم مَّوَدَّةًۭ وَرَحْمَةً﴾ [الروم: ٢١]. وزاد السعدي في بيانها ما يحصل به من «الاستمتاع واللذة والمنفعة بوجود الأولاد وتربيتهم، والسكون إليها»، وقال: «فلا تجد بين أحد في الغالب مثل ما بين الزوجين من المودة والرحمة» (ص٦٣٩). وأمّا العفّةُ وإحصانُ الفرج فمقصدٌ رابعٌ نصَّ عليه الحديث: «مَنِ اسْتَطَاعَ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ» (البخاري، ١٩٠٥).',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): الروم ٢١؛ تيسير الكريم الرحمن للسعدي (ت اللويحق): ص٦٣٩ (تفسير سورة الروم)؛ صحيح البخاري (ط السلطانية): ١٩٠٥ (ج٣/ص٢٦، باب الصوم لمن خاف على نفسه العزبة) | الكلمات المفتاحية: نكاح، أسرة، مودة',
  evidence = '﴿وَمِنْ ءَايَٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةًۭ وَرَحْمَةً ۚ إِنَّ فِى ذَٰلِكَ لَءَايَٰتٍۢ لِّقَوْمٍۢ يَتَفَكَّرُونَ﴾ [الروم: ٢١]. قال السعدي عندها: «{لِتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً} بما رتب على الزواج من الأسباب الجالبة للمودة والرحمة. فحصل بالزوجة الاستمتاع واللذة والمنفعة بوجود الأولاد وتربيتهم، والسكون إليها، فلا تجد بين أحد في الغالب مثل ما بين الزوجين من المودة والرحمة» (ص٦٣٩). وأمّا العفّةُ فمنصوصةٌ في حديث ابن مسعود: «مَنِ اسْتَطَاعَ الْبَاءَةَ فَلْيَتَزَوَّجْ، فَإِنَّهُ أَغَضُّ لِلْبَصَرِ وَأَحْصَنُ لِلْفَرْجِ» (صحيح البخاري، ١٩٠٥، ج٣/ص٢٦).',
  verification_status = 'verified'
WHERE id = 'df203e32-c210-4dc0-a0ff-95b2ada270be'
  AND reference = 'القرآن الكريم؛ تفسير السعدي | الكلمات المفتاحية: نكاح، أسرة، مودة'
  AND evidence = 'قال تعالى: ﴿وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَاجًا﴾ [الروم: 21].'
  AND answer = 'من مقاصده العفة والسكن وبناء الأسرة على المودة والرحمة.';

-- f051352e | ما أصل الدعوة إلى الله؟
UPDATE qa_questions SET
  answer = 'أصلُ الدعوة ما نصَّت عليه الآية: ﴿ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ﴾ [النحل: ١٢٥]، وحدَّ الطبريُّ ألفاظَها الأربعةَ تحديدًا: «سَبِيلِ رَبِّكَ» هو «شريعةِ ربِّك التي شرَعَها لخلقِه، وهو الإسلامُ»؛ و«الحكمة» هي «بوحيِ اللهِ الذى يُوحِيه إليك، وكتابِه الذي يُنْزِلُه عليك»؛ و«الموعظة الحسنة» هي «العِبَرِ الجميلةِ التي جعَلها اللهُ حُجَّةً عليهم في كتابِه»؛ والمجادلةُ بالأحسن «أن تَصْفَحَ عما نالوا به عِرْضَك من الأذى» (جامع البيان، ج١٤/ص٤٠٠). فمادّةُ الدعوة وحيٌ منزَّل لا رأيٌ مجرَّد، وطريقتُها العِبَرُ القرآنيّةُ والصفحُ عن الأذى.',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): النحل ١٢٥؛ جامع البيان عن تأويل آي القرآن للطبري (ت التركي): ج١٤/ص٤٠٠ | الكلمات المفتاحية: دعوة، حكمة، موعظة',
  evidence = '﴿ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ﴾ [النحل: ١٢٥]. قال الطبريُّ في تأويلها: «ادْعُ يا محمدُ من أرْسَلك إليه ربُّك بالدعاءِ إلى طاعتِه، ﴿إِلَى سَبِيلِ رَبِّكَ﴾. يقولُ: إلى شريعةِ ربِّك التي شرَعَها لخلقِه، وهو الإسلامُ، ﴿بِالْحِكْمَةِ﴾. يقولُ: بوحيِ اللهِ الذى يُوحِيه إليك، وكتابِه الذي يُنْزِلُه عليك، ﴿وَالْمَوْعِظَةِ الْحَسَنَةِ﴾. يقولُ: وبالعِبَرِ الجميلةِ التي جعَلها اللهُ حُجَّةً عليهم في كتابِه»، ثم قال في ﴿وَجَٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ﴾: «يقولُ: وخاصِمْهم بالخصومةِ التي هي أحسنُ من غيرِها؛ أن تَصْفَحَ عما نالوا به عِرْضَك من الأذى» (ج١٤/ص٤٠٠).',
  verification_status = 'verified'
