-- e941f220 | ما حكم أكل الميتة عند الاضطرار؟
UPDATE qa_questions SET
  answer = 'يُباح أكلُ الميتة للمضطرّ بنصّ ﴿فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَلَآ إِثْمَ عَلَيْهِ﴾ [البقرة: ١٧٣]، لكنّه مقيَّدٌ بثلاثة قيودٍ منصوصةٍ في تفسير ابن كثير للآية (ج١/ص٤٨٢): الأوّل ألّا يجد سواها — «عند فقد غيرها من الأطعمة» — بل نقل عن القرطبي أنه «إذا وجد المضطر ميتة وطعام الغير بحيث لا قطع فيه ولا أذى، فإنه لا يحل له أكل الميتة بل يأكل طعام الغير بلا خلاف». والثاني ألّا يتجاوز سدَّ الرمق، فعن عطاء الخراساني «لا يأكل إلا العُلْقَة»، وعن ابن عباس «لا يشبع منها». والثالث ألّا يكون باغيًا ولا عاديًا، أي «في غير بغي ولا عدوان، وهو مجاوزة الحد»، وفسَّره قتادةُ بأن يتعدّى «حلالا إلى حرام، وهو يجد عنه مندوحة».',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): البقرة ١٧٣؛ تفسير القرآن العظيم لابن كثير (ت السلامة): ج١/ص٤٨١-٤٨٢ (تفسير سورة البقرة)',
  evidence = '﴿إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ ۖ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍۢ وَلَا عَادٍۢ فَلَآ إِثْمَ عَلَيْهِ ۚ إِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌ﴾ [البقرة: ١٧٣]. قال ابن كثير: «ثم أباح تعالى تناول ذلك عند الضرورة والاحتياج إليها، عند فقد غيرها من الأطعمة، فقال: (فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلا عَادٍ) أي: في غير بغي ولا عدوان، وهو مجاوزة الحد (فَلا إِثْمَ عَلَيْهِ) أي: في أكل ذلك». وحدُّ ما يُتناول منقولٌ في الموضع نفسِه عن عطاء الخراساني: «لا يشوي من الميتة ليشتهيه ولا يطبخه، ولا يأكل إلا العُلْقَة، ويحمل معه ما يبلغه الحلال، فإذا بلغه ألقاه»، وعن ابن عباس: «لا يشبع منها»، وعن قتادة أنه «أن يتعدى حلالا إلى حرام، وهو يجد عنه مندوحة». ونقل ابن كثير عن القرطبي: «إذا وجد المضطر ميتة وطعام الغير بحيث لا قطع فيه ولا أذى، فإنه لا يحل له أكل الميتة بل يأكل طعام الغير بلا خلاف» (ج١/ص٤٨٢).',
  verification_status = 'verified'
WHERE id = 'e941f220-79ec-4090-9856-a6e94e4f4b50'
  AND reference = 'تفسير ابن كثير'
  AND evidence = 'قال تعالى: ﴿فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ﴾ [البقرة: 173].'
  AND answer = 'يجوز أكل الميتة عند الاضطرار الشديد الذي يُخشى معه الهلاك، بقدر ما يسد الرمق، رفعًا للحرج.';

-- e69c576d | كم عدد أولي العزم من الرسل وما أسماؤهم؟
UPDATE qa_questions SET
  answer = 'أولو العزم خمسةٌ، وتعيينُهم مأخوذٌ من الآية نفسِها لا من تعدادٍ خارجها: ﴿وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّۦنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍۢ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ﴾ [الأحزاب: ٧] — فهم: محمدٌ ﷺ (وهو المخاطَبُ بـ﴿وَمِنكَ﴾)، ونوحٌ، وإبراهيمُ، وموسى، وعيسى ابنُ مريم. قال السعديُّ: «ومن أولي العزم -وهم، هؤلاء الخمسة المذكورون- خصوصًا» (ص٦٥٩). والذي أُخذ عليهم هو «ميثاقهم الغليظ وعهدهم الثقيل المؤكد، على القيام بدين الله والجهاد في سبيله».',
  reference = 'مصحف المشروع (رواية حفص برسم عثماني): الأحزاب ٧؛ تيسير الكريم الرحمن للسعدي (ت اللويحق): ص٦٥٩ (تفسير سورة الأحزاب)',
  evidence = '﴿وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّۦنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍۢ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ ۖ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًۭا﴾ [الأحزاب: ٧]. قال السعديُّ عند هذه الآية: «يخبر تعالى أنه أخذ من النبيين عمومًا، ومن أولي العزم -وهم، هؤلاء الخمسة المذكورون- خصوصًا، ميثاقهم الغليظ وعهدهم الثقيل المؤكد، على القيام بدين الله والجهاد في سبيله» (ص٦٥٩). فالخمسةُ هم المسمَّوْن في الآية نفسِها، والنبيُّ ﷺ داخلٌ فيهم بقوله ﴿وَمِنكَ﴾.',
  verification_status = 'verified'
WHERE id = 'e69c576d-27c2-4c52-9586-abd27f088c28'
  AND reference = 'تفسير السعدي'
  AND evidence = 'قال تعالى: ﴿وَإِذْ أَخَذْنَا مِنَ النَّبِيِّينَ مِيثَاقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَاهِيمَ وَمُوسَىٰ وَعِيسَى ابْنِ مَرْيَمَ﴾ [الأحزاب: 7].'
  AND answer = 'أولو العزم من الرسل خمسة، وهم: نوح وإبراهيم وموسى وعيسى ومحمد عليهم الصلاة والسلام، وقد خصّهم الله بالصبر والثبات في الدعوة.';

-- f7da84b9 | ما معنى "أسباب النزول" في علوم القرآن؟
UPDATE qa_questions SET
  answer = '«أسبابُ النزول» اسمٌ للقسم الثاني من قسمَي النزول؛ قال الجعبريُّ فيما نقله السيوطيُّ: «نُزُولِ الْقُرْآنِ عَلَى قِسْمَيْنِ: قِسْمٌ نَزَلَ ابْتِدَاءً وَقِسْمٌ نَزَلَ عَقِبَ وَاقِعَةٍ أَوْ سُؤَالٍ» (الإتقان، ج١/ص١٠٧) — فسببُ النزول هو تلك الواقعةُ أو ذلك السؤال. وفائدتُه في فهم الآية نصَّ عليها الواحديُّ: «لِامْتِنَاعِ مَعْرِفَةِ تَفْسِيرِ الْآيَةِ وَقَصْدِ سَبِيلِهَا، دُونَ الْوُقُوفِ عَلَى قِصَّتِهَا وَبَيَانِ نُزُولِهَا» (أسباب نزول القرآن، ص٨)، وابنُ تيمية: «الْعِلْمَ بِالسَّبَبِ يُوَرِّثُ الْعِلْمَ بِالْمُسَبَّبِ»، وعدَّ السيوطيُّ منها «مَعْرِفَةُ وَجْهِ الْحِكْمَةِ الْبَاعِثَةِ عَلَى تَشْرِيعِ الْحُكْمِ» (الإتقان، ج١/ص١٠٧-١٠٨).',
  reference = 'أسباب نزول القرآن للواحدي (ت الحميدان): ص٨ (مقدمة المؤلف)؛ الإتقان في علوم القرآن للسيوطي: ج١/ص١٠٧-١٠٨ (النوع التاسع: معرفة سبب النزول) | الكلمات المفتاحية: أسباب النزول',
  evidence = 'قسمةُ النزول منقولةٌ في الإتقان عن الجعبريّ: «نُزُولِ الْقُرْآنِ عَلَى قِسْمَيْنِ: قِسْمٌ نَزَلَ ابْتِدَاءً وَقِسْمٌ نَزَلَ عَقِبَ وَاقِعَةٍ أَوْ سُؤَالٍ» (ج١/ص١٠٧) — والقسمُ الثاني هو موردُ «أسباب النزول». وفائدتُه في التفسير منصوصةٌ عند الواحديِّ في مقدمة كتابه: «لِامْتِنَاعِ مَعْرِفَةِ تَفْسِيرِ الْآيَةِ وَقَصْدِ سَبِيلِهَا، دُونَ الْوُقُوفِ عَلَى قِصَّتِهَا وَبَيَانِ نُزُولِهَا» (ص٨). وعدَّ السيوطيُّ من فوائده «مَعْرِفَةُ وَجْهِ الْحِكْمَةِ الْبَاعِثَةِ عَلَى تَشْرِيعِ الْحُكْمِ» (ج١/ص١٠٧)، ونقل: «وَقَالَ ابْنُ تَيْمِيَةَ: مَعْرِفَةُ سَبَبِ النُّزُولِ يُعِينُ عَلَى فَهْمِ الْآيَةِ فَإِنَّ الْعِلْمَ بِالسَّبَبِ يُوَرِّثُ الْعِلْمَ بِالْمُسَبَّبِ» (ج١/ص١٠٨).',
  verification_status = 'verified'
WHERE id = 'f7da84b9-afd1-40ad-a01c-3a0fcb5d424f'
